<?php
declare(strict_types=1);

require __DIR__.'/bootstrap.php';
require tamiran_private_root().'/v2-core.php';
require tamiran_private_root().'/sms-service.php';

function sms_payload(PDO $pdo,array $scope):array
{
    if($scope['role']!=='repair_manager')throw new TamiranApiException('تنظیمات پیامک فقط برای مدیر قابل مشاهده است.',403);$providers=$pdo->prepare('SELECT id,public_id,provider_code,display_name,settings_json,is_active,created_at,updated_at FROM tamiran_sms_providers WHERE shop_id=:shop ORDER BY is_active DESC,id');$providers->execute(['shop'=>$scope['shop_id']]);$templates=$pdo->prepare('SELECT public_id,event_code,title,body_template,lookup_template,is_enabled,updated_at FROM tamiran_sms_templates WHERE shop_id=:shop ORDER BY event_code');$templates->execute(['shop'=>$scope['shop_id']]);$messages=$pdo->prepare('SELECT public_id,event_code,recipient_mobile,status,provider_message_id,attempts,max_attempts,next_attempt_at,last_error,related_type,related_public_id,created_at,sent_at FROM tamiran_sms_messages WHERE shop_id=:shop ORDER BY created_at DESC LIMIT 500');$messages->execute(['shop'=>$scope['shop_id']]);return['providers'=>$providers->fetchAll(),'templates'=>$templates->fetchAll(),'messages'=>$messages->fetchAll()];
}

function sms_configure(PDO $pdo,array $scope,array $input):array
{
    if($scope['role']!=='repair_manager')throw new TamiranApiException('تنظیم ارائه‌دهنده فقط برای مدیر مجاز است.',403);$providerCode=(string)($input['providerCode']??'');if(!in_array($providerCode,['kavenegar','generic_rest'],true))throw new TamiranApiException('ارائه‌دهنده معتبر نیست.');if($providerCode!=='kavenegar')throw new TamiranApiException('در بتای فعلی آداپتور کاوه‌نگار آماده است؛ آداپتورهای دیگر از همین رابط افزوده می‌شوند.',409);$apiKey=v2_text($input['apiKey']??'','کلید API',240);$settings=is_array($input['settings']??null)?$input['settings']:[];$public=tamiran_id();$cipher=tamiran_encrypt_secret(json_encode(['apiKey'=>$apiKey],JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));$pdo->beginTransaction();try{$existing=$pdo->prepare('SELECT id,public_id FROM tamiran_sms_providers WHERE shop_id=:shop AND provider_code=:code FOR UPDATE');$existing->execute(['shop'=>$scope['shop_id'],'code'=>$providerCode]);$row=$existing->fetch();if(is_array($row)){$pdo->prepare('UPDATE tamiran_sms_providers SET display_name=:name,credentials_ciphertext=:credentials,settings_json=:settings,is_active=1,updated_at=NOW() WHERE id=:id')->execute(['name'=>v2_text($input['displayName']??'کاوه‌نگار','عنوان',180),'credentials'=>$cipher,'settings'=>v2_json($settings),'id'=>$row['id']]);$public=$row['public_id'];}else{$pdo->prepare('INSERT INTO tamiran_sms_providers(public_id,shop_id,provider_code,display_name,credentials_ciphertext,settings_json,created_by_user_id) VALUES(:public,:shop,:code,:name,:credentials,:settings,:actor)')->execute(['public'=>$public,'shop'=>$scope['shop_id'],'code'=>$providerCode,'name'=>v2_text($input['displayName']??'کاوه‌نگار','عنوان',180),'credentials'=>$cipher,'settings'=>v2_json($settings),'actor'=>$scope['actor']['id']]);}tamiran_audit($pdo,$scope['shop_id'],$scope['branch_id'],$scope['actor']['id'],'sms.provider.configure','tamiran_sms_provider',$public,null,['provider'=>$providerCode,'settings'=>$settings],'کلید API به‌صورت رمزگذاری‌شده ذخیره شد');$pdo->commit();}catch(Throwable$error){if($pdo->inTransaction())$pdo->rollBack();throw$error;}return['saved'=>true,'publicId'=>$public];
}

function sms_save_template(PDO $pdo,array $scope,array $input):array
{
    if($scope['role']!=='repair_manager')throw new TamiranApiException('ویرایش قالب پیامک فقط برای مدیر مجاز است.',403);$event=v2_text($input['eventCode']??'','کد رویداد',80);if(!preg_match('/^[a-z0-9._-]{2,80}$/',$event))throw new TamiranApiException('کد رویداد معتبر نیست.');$body=v2_text($input['bodyTemplate']??'','متن قالب',1800);$public=tamiran_id();$pdo->prepare('INSERT INTO tamiran_sms_templates(public_id,shop_id,event_code,title,body_template,lookup_template,is_enabled,updated_by_user_id) VALUES(:public,:shop,:event,:title,:body,:lookup,:enabled,:actor) ON DUPLICATE KEY UPDATE title=VALUES(title),body_template=VALUES(body_template),lookup_template=VALUES(lookup_template),is_enabled=VALUES(is_enabled),updated_by_user_id=VALUES(updated_by_user_id),updated_at=NOW()')->execute(['public'=>$public,'shop'=>$scope['shop_id'],'event'=>$event,'title'=>v2_text($input['title']??'','عنوان قالب',180),'body'=>$body,'lookup'=>v2_text($input['lookupTemplate']??'','قالب Lookup',120,false),'enabled'=>empty($input['isEnabled'])?0:1,'actor'=>$scope['actor']['id']]);return['saved'=>true];
}

function sms_request_otp(PDO $pdo,array $scope,array $input):array
{
    $purpose=(string)($input['purpose']??'');$subject=v2_text($input['subjectPublicId']??'','موضوع',80);if(!in_array($purpose,['estimate','delivery','representative_delivery','portal_action','mobile_change'],true))throw new TamiranApiException('هدف OTP معتبر نیست.');$mobile=tamiran_mobile((string)($input['mobile']??''));tamiran_public_rate_limit('otp|'.$scope['shop_id'].'|'.$mobile,5,900,900);$providerStatement=$pdo->prepare("SELECT * FROM tamiran_sms_providers WHERE shop_id=:shop AND is_active=1 ORDER BY id LIMIT 1");$providerStatement->execute(['shop'=>$scope['shop_id']]);$providerRow=$providerStatement->fetch();if(!is_array($providerRow))throw new TamiranApiException('ارائه‌دهنده پیامک فعال تنظیم نشده است.',409);$settings=json_decode((string)$providerRow['settings_json'],true)?:[];$template=(string)($settings['otpTemplate']??'');if($template==='')throw new TamiranApiException('نام قالب Lookup برای OTP در تنظیمات ارائه‌دهنده وارد نشده است.',409);$code=(string)random_int(100000,999999);$public=tamiran_id();$expires=date('Y-m-d H:i:s',time()+180);$pdo->prepare('INSERT INTO tamiran_sms_otps(public_id,shop_id,purpose,subject_public_id,mobile,code_hash,expires_at) VALUES(:public,:shop,:purpose,:subject,:mobile,:hash,:expires)')->execute(['public'=>$public,'shop'=>$scope['shop_id'],'purpose'=>$purpose,'subject'=>$subject,'mobile'=>$mobile,'hash'=>tamiran_sms_otp_hash($scope['shop_id'],$purpose,$subject,$mobile,$code),'expires'=>$expires]);try{$provider=tamiran_sms_provider_from_row($providerRow);$result=$provider->lookup($mobile,$template,[$code]);$pdo->prepare("INSERT INTO tamiran_sms_messages(public_id,shop_id,provider_id,event_code,recipient_mobile,body,status,provider_message_id,attempts,max_attempts,next_attempt_at,idempotency_key,related_type,related_public_id,sent_at) VALUES(:message,:shop,:provider,:event,:mobile,'[OTP protected]','sent',:provider_message,1,1,NOW(),:idempotency,'otp',:related,NOW())")->execute(['message'=>tamiran_id(),'shop'=>$scope['shop_id'],'provider'=>$providerRow['id'],'event'=>'otp.'.$purpose,'mobile'=>$mobile,'provider_message'=>$result['messageId'],'idempotency'=>'otp-'.$public,'related'=>$subject]);}catch(Throwable$error){$pdo->prepare('UPDATE tamiran_sms_otps SET attempts=max_attempts WHERE public_id=:public')->execute(['public'=>$public]);tamiran_log('error','sms_otp_send_failed',['shop_id'=>$scope['shop_id'],'purpose'=>$purpose,'message'=>$error->getMessage()]);throw new TamiranApiException('ارسال کد یک‌بارمصرف انجام نشد؛ دوباره تلاش کنید.',503);}return['requested'=>true,'requestId'=>$public,'expiresAt'=>$expires];
}

tamiran_api(static function():array{$pdo=tamiran_db();$scope=v2_scope();v2_require_capability(v2_product_policy($pdo,$scope),'smsEnabled','ماژول پیامک برای این تعمیرگاه فعال نیست.');$method=$_SERVER['REQUEST_METHOD']??'GET';if($method==='GET')return sms_payload($pdo,$scope);if($method!=='POST')throw new TamiranApiException('روش درخواست مجاز نیست.',405);tamiran_require_csrf();$input=tamiran_json_body();return match((string)($input['action']??'')){'configure'=>sms_configure($pdo,$scope,$input),'template_save'=>sms_save_template($pdo,$scope,$input),'otp_request'=>sms_request_otp($pdo,$scope,$input),default=>throw new TamiranApiException('عملیات پیامک معتبر نیست.'),};});
